export default async function install(app) {
 const [serviceArea, networkService, ServiceAreaParameters, FeatureSet, Graphic] = await Promise.all([app.import('esri/rest/serviceArea'),app.import('esri/rest/networkService'),app.import('esri/rest/support/ServiceAreaParameters'),app.import('esri/rest/support/FeatureSet'),app.import('esri/Graphic')]);
 const stations = app.layers[app.config.layerId];
 const mount = app.getMount('station-workflow');
 const root = document.createElement('div'); root.style.cssText='display:grid;gap:12px;min-width:0;color:var(--app-text)';
 const label=document.createElement('calcite-label'); label.textContent='Search police stations';
 const input=document.createElement('calcite-input-text'); input.id='station-search-input'; input.placeholder='Name, precinct number or address'; input.setAttribute('clearable',''); input.setAttribute('icon','magnifying-glass'); label.append(input);
 const searchStatus=document.createElement('p'); searchStatus.style.cssText='margin:0;color:var(--app-text-muted)'; searchStatus.textContent='Search stations or click a station on the map.';
 const matches=document.createElement('div'); matches.id='station-search-results'; matches.style.cssText='display:grid;gap:6px;min-width:0';
 const card=document.createElement('calcite-card'); const heading=document.createElement('div'); heading.slot='heading'; heading.textContent='No station selected'; const address=document.createElement('div'); address.slot='description'; const status=document.createElement('p'); status.setAttribute('role','status'); status.setAttribute('aria-live','polite'); status.textContent='Select a station to generate its coverage.'; card.append(heading,address,status);
 const reset=document.createElement('calcite-button'); reset.id='station-clear'; reset.textContent='Clear coverage'; reset.appearance='outline';
 const note=document.createElement('p'); note.style.cssText='margin:0;color:var(--app-text-muted);font-size:12px;line-height:1.5'; note.textContent='10 minutes driving outward from the station. No departure time or live-traffic scenario is set. Standard road restrictions apply; dispatch delay and emergency-driving privileges are not modeled. ArcGIS routing access and credits may be required. Source: NYC Emergency Management.';
 root.append(label,searchStatus,matches,card,reset,note); mount.replaceChildren(root);
 const areas=await app.createResultLayer({id:'police-response-areas',title:'10-minute driving coverage',geometryType:'polygon',fields:[{name:'Station',type:'string'},{name:'Minutes',type:'double'}],renderer:{type:'simple',symbol:{type:'simple-fill',color:[36,104,180,0.18],outline:{color:[36,104,180,0.9],width:1.8}}},popupTemplate:{title:'{Station}: 10-minute driving coverage',content:'Estimated outward driving coverage; not a guaranteed emergency response time.'}});
 app.map.reorder(areas.layer,0);
 let generation=0, searchGeneration=0, timer, highlight, mode, disposed=false;
 let state={phase:'idle',station:null,polygonCount:0,searchPhase:'idle',matchCount:0};
 const listen=(el,event,handler)=>{el.addEventListener(event,handler);app.onCleanup(()=>el.removeEventListener(event,handler));};
 const chooseMode=async()=>{if(!mode){const description=await networkService.fetchServiceDescription(app.config.serviceAreaUrl); const modes=description.supportedTravelModes||[];mode=modes.find(m=>m.id===app.config.defaultTravelMode && m.type==='automobile' && m.impedanceAttributeName===m.timeAttributeName)||modes.find(m=>m.type==='automobile' && m.impedanceAttributeName===m.timeAttributeName);app.assert(mode,'The routing service offers no time-based driving mode.');}return mode;};
 const select=async({graphic,objectId}={})=>{
  const seq=++generation; state={...state,phase:'loading',polygonCount:0,station:null}; status.textContent='Generating 10-minute driving coverage…'; heading.textContent='Loading station…';address.textContent='';highlight?.remove();highlight=null;await areas.clear();
  try {const id=objectId??graphic?.getObjectId(); app.assert(id!=null,'Choose a station first.');const q=stations.createQuery();q.objectIds=[Number(id)];q.outFields=['OBJECTID','FACILITY_NAME','FACILITY_ADDRESS','BOROUGH','POLICE_PREC'];q.returnGeometry=true;q.outSpatialReference=app.view.spatialReference;
   const response=await stations.queryFeatures(q);if(seq!==generation||disposed)return {stale:true};const station=response.features[0];app.assert(station?.geometry,'This station has no usable location.');const a=station.attributes;heading.textContent=String(a.FACILITY_NAME);address.textContent=String(a.FACILITY_ADDRESS||'')+' · '+String(a.BOROUGH||'');state.station=String(a.FACILITY_NAME);
   const lv=await app.view.whenLayerView(stations);if(seq!==generation||disposed)return {stale:true};highlight=lv.highlight(station.getObjectId());
   const travelMode=await chooseMode();if(seq!==generation||disposed)return {stale:true};
   const result=await serviceArea.solve(app.config.serviceAreaUrl,new ServiceAreaParameters({facilities:new FeatureSet({features:[new Graphic({geometry:station.geometry,attributes:{Name:a.FACILITY_NAME}})]}),travelMode,defaultBreaks:[10],travelDirection:'from-facility',outSpatialReference:app.view.spatialReference,outputPolygons:'simplified',outputLines:'none',returnFacilities:true,trimOuterPolygon:true}),null);
   if(seq!==generation||disposed)return {stale:true};const polygons=(result.serviceAreaPolygons?.features||[]).filter(f=>f.geometry);await areas.replaceFeatures(polygons.map(f=>({geometry:f.geometry,attributes:{Station:String(a.FACILITY_NAME),Minutes:10}})));if(seq!==generation||disposed)return {stale:true};
   state={...state,phase:polygons.length?'ready':'empty',polygonCount:polygons.length,mode:travelMode.name};status.textContent=polygons.length?'10-minute driving coverage ready.':'No reachable service area was returned for this station.';
   if(polygons.length) await app.view.goTo(polygons.map(f=>f.geometry)).catch(()=>{});
   return {...state};
  }catch(error){if(seq!==generation||disposed)return {stale:true};state={...state,phase:'error',polygonCount:0};status.textContent='Coverage could not be generated: '+(error.message||String(error));return {...state,error:status.textContent};}
 };
 const search=async({text}={})=>{const seq=++searchGeneration;const value=String(text??input.value??'').trim();matches.replaceChildren();if(!value){searchStatus.textContent='Search stations or click a station on the map.';state={...state,searchPhase:'idle',matchCount:0};return {count:0};}state={...state,searchPhase:'loading'};searchStatus.textContent='Searching stations…';try{const escaped=value.replace(/'/g,"''").replace(/[%_]/g,'');const q=stations.createQuery();q.where="(UPPER(FACILITY_NAME) LIKE '%"+escaped.toUpperCase()+"%' OR UPPER(FACILITY_ADDRESS) LIKE '%"+escaped.toUpperCase()+"%'"+(/^\d+$/.test(value)?' OR POLICE_PREC = '+Number(value):'')+')';q.outFields=['OBJECTID','FACILITY_NAME','FACILITY_ADDRESS','POLICE_PREC'];q.returnGeometry=false;q.orderByFields=['POLICE_PREC ASC'];q.num=8;const r=await stations.queryFeatures(q);if(seq!==searchGeneration||disposed)return {stale:true};state={...state,searchPhase:'ready',matchCount:r.features.length};searchStatus.textContent=r.features.length?'Select a station below. Up to 8 matches shown.':'No matching stations. Try a precinct number or street name.';for(const f of r.features){const b=document.createElement('calcite-button');b.appearance='outline';b.width='full';b.setAttribute('data-station-id',String(f.getObjectId()));b.textContent=f.attributes.FACILITY_NAME+' — '+f.attributes.FACILITY_ADDRESS;matches.append(b);}return {count:r.features.length,ids:r.features.map(f=>f.getObjectId())};}catch(error){if(seq!==searchGeneration||disposed)return {stale:true};state={...state,searchPhase:'error',matchCount:0};searchStatus.textContent='Station search failed: '+(error.message||String(error));return {error:searchStatus.textContent};}};
 const clear=async()=>{generation++;searchGeneration++;clearTimeout(timer);highlight?.remove();highlight=null;await areas.clear();input.value='';matches.replaceChildren();heading.textContent='No station selected';address.textContent='';status.textContent='Select a station to generate its coverage.';searchStatus.textContent='Search stations or click a station on the map.';state={phase:'idle',station:null,polygonCount:0,searchPhase:'idle',matchCount:0};return {...state};};
 app.actions.register('station-select',select);app.actions.register('station-search',search);app.actions.register('station-clear',clear);app.actions.register('station-state',()=>({...state,statusText:status.textContent,searchText:searchStatus.textContent}));
 listen(input,'calciteInputTextInput',()=>{clearTimeout(timer);searchGeneration++;timer=setTimeout(()=>search({text:input.value}),250);});
 listen(matches,'click',event=>{const b=event.target.closest('calcite-button[data-station-id]');if(b)select({objectId:Number(b.getAttribute('data-station-id'))});});listen(reset,'click',clear);
 app.onCleanup(()=>{disposed=true;generation++;searchGeneration++;clearTimeout(timer);highlight?.remove();mount.replaceChildren();});
}